<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { knowledgeApi } from '../../api/knowledge'; import type { KnowledgeCategory } from '../../types'; import { apiErrorMessage } from '../../utils/errors'; import PageHeading from '../../components/PageHeading.vue'
const route=useRoute();const router=useRouter();const editing=computed(()=>Boolean(route.params.id));const id=route.params.id as string|undefined;const categories=ref<KnowledgeCategory[]>([]);const saving=ref(false);const loading=ref(editing.value);const formRef=ref<FormInstance>();const form=reactive({title:'',categoryId:'',content:'',version:0});const rules:FormRules={title:[{required:true,message:'Enter a title',trigger:'blur'}],categoryId:[{required:true,message:'Choose a category',trigger:'change'}],content:[{required:true,message:'Write the article content',trigger:'blur'}]}
onMounted(async()=>{try{categories.value=(await knowledgeApi.categories()).data;if(editing.value&&id){const {data}=await knowledgeApi.article(id);form.title=data.title;form.categoryId=data.categoryId;form.content=data.content||'';form.version=data.version}}catch(e){ElMessage.error(apiErrorMessage(e));router.back()}finally{loading.value=false}})
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;saving.value=true;try{const response=editing.value&&id?await knowledgeApi.updateArticle(id,{title:form.title,content:form.content,categoryId:form.categoryId,expectedVersion:form.version}):await knowledgeApi.createArticle({title:form.title,content:form.content,categoryId:form.categoryId});ElMessage.success(editing.value?'Article updated':'Draft created');await router.replace(`/knowledge/articles/${response.data.id}`)}catch(e){ElMessage.error(apiErrorMessage(e))}finally{saving.value=false}}
</script>
<template><div v-loading="loading" class="article-editor-page"><PageHeading :title="editing?'Edit article':'Create article'" description="Write clear, practical guidance that teammates can trust." /><section class="content-card form-card"><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><div class="two-column-form"><el-form-item label="Title" prop="title"><el-input v-model="form.title" size="large" maxlength="200" show-word-limit /></el-form-item><el-form-item label="Category" prop="categoryId"><el-select v-model="form.categoryId" size="large" placeholder="Choose category"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id" /></el-select></el-form-item></div><el-form-item label="Content" prop="content"><el-input v-model="form.content" type="textarea" :rows="18" maxlength="100000" placeholder="Write the article in plain text or Markdown…" /></el-form-item><div class="editor-note">Plain text and Markdown are stored as authored. HTML is never rendered.</div><div class="form-actions"><el-button @click="router.back()">Cancel</el-button><el-button type="primary" :loading="saving" @click="save">{{ editing?'Save changes':'Create draft' }}</el-button></div></el-form></section></div></template>
